    Bug 1987793 - Load RSS feed icons only after about:3pane is fully loaded. r=freaktechnik
    Fixes browser_folderPaneContext.js, which fails if run by itself.

    Differential Revision: https://phabricator.services.mozilla.com/D277942

diff --git a/mail/base/content/widgets/folder-tree-row.mjs b/mail/base/content/widgets/folder-tree-row.mjs
index bcf930d54bf..29f749d24d8 100644
--- a/mail/base/content/widgets/folder-tree-row.mjs
+++ b/mail/base/content/widgets/folder-tree-row.mjs
@@ -449,17 +449,10 @@ class FolderTreeRow extends HTMLLIElement {
    *
    * @param {nsIMsgFolder} folder
    */
-  setFolderPropertiesFromFolder(folder) {
+  async setFolderPropertiesFromFolder(folder) {
     if (folder.server.type != "rss") {
       return;
     }
-    const urls = !folder.isServer
-      ? lazy.FeedUtils.getFeedUrlsInFolder(folder)
-      : null;
-    if (urls?.length == 1) {
-      const url = urls[0];
-      this.icon.style = `content: url("page-icon:${url}");`;
-    }
     const props = lazy.FeedUtils.getFolderProperties(folder);
     for (const property of ["hasError", "isBusy", "isPaused"]) {
       if (props.includes(property)) {
@@ -468,6 +461,21 @@ class FolderTreeRow extends HTMLLIElement {
         delete this.dataset[property];
       }
     }
+    const urls = !folder.isServer
+      ? lazy.FeedUtils.getFeedUrlsInFolder(folder)
+      : null;
+    if (urls?.length == 1) {
+      const url = urls[0];
+      if (document.readyState != "complete") {
+        // If about:3pane isn't fully loaded, wait until it is before setting
+        // the row icon, otherwise the icon will be included in the page's
+        // load group and delay everything else that's waiting on the load.
+        await new Promise(resolve =>
+          window.addEventListener("load", resolve, { once: true })
+        );
+      }
+      this.icon.style = `content: url("page-icon:${url}");`;
+    }
   }

